{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest analogue sharing the 6-methoxyquinoline and vinyl-amine scaffold, had an absolute oral bioavailability of 80% versus IV in healthy subjects, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, which contains the same 6-methoxyquinoline core, has an absolute bioavailability of about 85% in humans, supporting high F despite lower overall similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Alizapride, a basic heteroaromatic drug with a methoxy-substituted ring, showed 72.5% absolute oral availability versus IV, supporting high F for a basic amine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Midodrine, a polar methoxyphenyl drug, reached 93% absolute bioavailability in healthy volunteers, indicating that polar/ionizable groups do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tegaserod, a methoxyindole drug, had only about 10% absolute bioavailability under fasted conditions; this is contradictory in direction but has low transferability to the query due to a different scaffold and low Morgan similarity.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine and several 6-methoxyquinoline/basic-amine drugs show high absolute oral bioavailability (73-93%), while low-F examples are structurally distant; therefore the query is predicted to have F >= 20% (high).",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement exists for the exact query molecule.",
    "The closest analogue viqualine was not explicitly studied under fasted conditions, while the query condition is fasted.",
    "The quinuclidine ring and carbinol linker in the query differ from viqualine's piperidine and propyl chain, which could alter first-pass metabolism or efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

